def install(root):
    root=Path(root)
    if not (root/'Invoice_Desktop.py').is_file():
        raise ValueError('Save and run this installer in the existing invoice reader source folder containing Invoice_Desktop.py.')
    mismatches=[]
    for name,digest in ENGINE.items():
        path=root/name
        if not path.is_file() or hashlib.sha256(path.read_bytes()).hexdigest() not in (digest,WINDOWS_ENGINE[name]):
            mismatches.append(name)
    if mismatches:
        raise ValueError('This UI requires the matching locked Reader 7.30 source. No files changed. Different or missing files: '+', '.join(mismatches[:6]))
    target_names=list(FILES)
    for name in target_names:
        if (root/name).is_symlink():raise ValueError('No files changed: installation target is a symbolic link: '+name)
    backup=root/'.invoice_app'/'code_backups'/('billsync_source_'+datetime.now().strftime('%Y%m%d_%H%M%S_%f')+'_'+uuid.uuid4().hex[:6])
    backup.mkdir(parents=True)
    previous={}
    for name in target_names:
        path=root/name
        if path.is_file():
            original=path.read_bytes();(backup/name).write_bytes(original)
            previous[name]=hashlib.sha256(original).hexdigest()
    (backup/'BACKUP_MANIFEST.json').write_text(json.dumps({'previous_files':previous,'new_files':[name for name in target_names if name not in previous]},indent=2),encoding='utf-8')
    for name,text in FILES.items():
        (root/name).write_bytes(text.encode('utf-8'))
    return backup


def main():
    root=Path.cwd()
    if not (root/'Invoice_Desktop.py').is_file():root=Path(__file__).resolve().parent
    try:backup=install(root)
    except (ValueError,OSError) as exc:
        print(str(exc));return 1
    print('BillSync UI 1.1 source installed. Backup: '+str(backup))
    print('Reader, AI processing, units, masters, vouchers and Import ALL code unchanged.')
    print('No AI requests, XML generation or Tally imports sent.')
    print('Next run:')
    print(r'.venv\Scripts\python.exe -m pip install -r requirements-ui.txt')
    print(r'.venv\Scripts\python.exe BillSync_UI.py')
    return 0


if __name__=='__main__':raise SystemExit(main())
